class Counter:
    def __init__(self):
        self.value = 0
    def increment(self, step=1):
        self.value += step
        return self.value

class Volume:
    def __init__(self):
        self.level = 5
    def set_level(self, level):
        self.level = level
        return self.level

class Toggle:
    def __init__(self):
        self.enabled = False
    def set_enabled(self, value):
        self.enabled = bool(value)
        return self.enabled

class BoundedQueue:
    def __init__(self, capacity):
        self.capacity = capacity
        self.items = []
    def push(self, item):
        self.items.append(item)
        if len(self.items) > self.capacity:
            raise OverflowError('full')
        return len(self.items)
